class Solution {
public:
    string reorderSpaces(string text) {
        int n = text.size();
        int spaces = 0, words = 0;
        bool inWord = false;

        for (int i = 0; i < n; i++) {
            if (text[i] == ' ') {
                spaces++;
                inWord = false;
            } else {
                if (!inWord) {
                    words++;
                    inWord = true;
                }
            }
        }

        int gaps = (words > 1) ? spaces / (words - 1) : 0;
        int extra = (words > 1) ? spaces % (words - 1) : spaces;

        string result;
        result.reserve(n);
        int wordCount = 0;
        inWord = false;

        for (int i = 0; i < n; i++) {
            if (text[i] != ' ') {
                if (!inWord) {
                    if (wordCount > 0) {
                        result.append(gaps, ' ');
                    }
                    inWord = true;
                    wordCount++;
                }
                result.push_back(text[i]);
            } else {
                inWord = false;
            }
        }

        result.append(extra, ' ');
        return result;
    }
};
